interface ToolArgsMap {
  /** Execute a bash command (`bash -c`) and return its stdout/stderr. Each call runs in a fresh shell; pass `workdir` instead of using `cd`. Managed `$DSH_*` variables expose current harness environment facts. Long output is truncated to its tail; the full output is saved to a file whose path is reported when available. Provide `description` before `command` in the arguments. Before any delete or move, verify that the resolved absolute target path is the intended one; never run it against a computed path you have not checked. An unset variable expands to an empty string, so guard variables in such paths with `${VAR:?}`. Commands may run under a file sandbox; a blocked file operation is reported as `[sandbox: file access denied under <mode> mode]`, a policy denial: do not retry another way. */
  bash: {
    /** Clear, concise description of what this command does in active voice, 5-10 words (shown in the UI). Examples: "ls" → "List files in current directory"; "git status" → "Show working tree status"; "npm install" → "Install package dependencies". */
    description: string;
    /** The bash command to execute. */
    command: string;
    /** Timeout in milliseconds. The executor applies its configured default and cap; on expiry the command moves to the background as a job instead of being killed. */
    timeoutMs?: number;
    /** Working directory for this command. Defaults to the session workspace; a relative path is resolved against it. */
    workdir?: string;
    /** Run in the background and return a job id immediately (collect with job_output, stop with job_kill). No timeout applies. */
    run_in_background?: boolean;
    /** The narrowest wider sandbox mode for a one-shot retry of the exact command the sandbox just denied; the retry asks the user for approval. */
    sandbox_permissions?: "workspace-write" | "danger-full-access";
    /** Required with sandbox_permissions: one sentence for the user explaining why this exact command needs the wider access. Use the language of the user’s current request. */
    justification?: string;
  } & Record<string, JsonValue>;
  /** List the context tree: instructions, reference documents, and extra tools you can load on demand. Returns each node's path, title, and one line saying when to use it, never its body. Start with no path, then narrow; raise depth to see more levels at once (capped). */
  context_browse: {
    /** Node to list, as printed by an earlier listing. Omit for the top. */
    path?: string;
    /** Levels to list below the node. Default 1. */
    depth?: number;
    /** Entries to skip, to continue a listing that said more remain. Default 0. */
    offset?: number;
  } & Record<string, JsonValue>;
  /** Load nodes from the context tree. An instruction or source node adds its text to the conversation; a tool node makes those tools callable from your next step. Several paths in one call count as one change. Loaded text and tools are dropped when the conversation is compacted. */
  context_load: {
    /** Node paths from context_browse. A folder loads everything under it. */
    paths: string[];
  } & Record<string, JsonValue>;
  /** Record one short fact about this project for the project map, such as where something lives or a convention you had to discover. A background curator checks and files it; you get no reply to wait for. Cite the context sections (sec_… ids from context_browse) or evidence ("ref:" and a short pointer) it rests on. Do not record plans, progress, or anything already in the instructions. */
  context_note: {
    /** The fact, in one or two sentences. */
    text: string;
    /** Section ids or "ref:…" evidence the fact rests on. */
    cites?: string[];
  } & Record<string, JsonValue>;
  /** Edit an existing UTF-8 text file by replacing literal text. */
  edit: {
    /** Path to edit, resolved by the filesystem backend. Provide `file_path` before `old_string` and `new_string` in the arguments. */
    file_path: string;
    /** Literal text to replace. */
    old_string: string;
    /** Literal replacement text. Use an empty string to delete the match. */
    new_string: string;
    /** Replace all matches. Defaults to false; when false, old_string must appear exactly once. */
    replace_all?: boolean;
    /** The narrowest wider sandbox mode for a one-shot retry of the exact operation the sandbox just denied; the retry asks the user for approval. */
    sandbox_permissions?: "workspace-write" | "danger-full-access";
    /** Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access. Use the language of the user’s current request. */
    justification?: string;
  } & Record<string, JsonValue>;
  /** Find files, not directories, whose paths match a glob pattern, including hidden and ignored files. Returns up to 100 paths in modification-time order; a larger result keeps the first paths and reports where the complete list was saved. */
  glob: {
    /** Glob pattern to match file paths against (e.g. "**\/*.ts", "src/**\/*.test.js"). A pattern with no "/" matches the basename at any depth, so "*" and "*.ts" both search the whole tree; include a separator to anchor the depth. */
    pattern: string;
    /** Directory to search in. Defaults to the session workspace; a relative path resolves against it. */
    path?: string;
  } & Record<string, JsonValue>;
  /** Search file contents with a ripgrep regular expression. Returns matching lines with line numbers, grouped by file. Returns up to 250 matches; a larger result reports where the complete match list was saved. */
  grep: {
    /** Regular expression to search for (ripgrep syntax). */
    pattern: string;
    /** File or directory to search. Defaults to the session workspace; a relative path resolves against it. */
    path?: string;
    /** One glob filter for which files to search (e.g. "*.ts", "*.{js,jsx}"). Not a list; negation is not supported. */
    include?: string;
  } & Record<string, JsonValue>;
  /** Choose the sections granted up front at the start of every conversation, most important first. Keep it small: each costs context in every session. */
  map_core: {
    /** Map owner Session id; omit for your own conversation, specify for another map you curate. */
    root_session_id?: string;
    /** Revision from map_view; the edit is rejected if the map moved on. */
    expected_revision: number;
    /** Section ids in priority order; an empty list clears the core. */
    sections: string[];
  } & Record<string, JsonValue>;
  /** Create, replace, merge, or retire a group. set: path "Root/Origin/name" (Root is Instructions, Sources, or Tools; Origin is Global or Project), title, one-line summary saying when to use the members, and sections or tools; pass group_id to replace a group. merge: moves from_group and its notes into group_id. retire: removes group_id and its notes. */
  map_group: {
    /** Map owner Session id; omit for your own conversation, specify for another map you curate. */
    root_session_id?: string;
    /** What to do. */
    action: "set" | "merge" | "retire";
    /** Revision from map_view; the edit is rejected if the map moved on. */
    expected_revision: number;
    /** Existing group (replace, merge target, retire). */
    group_id?: string;
    /** merge: group to fold in. */
    from_group?: string;
    /** set: Root/Origin/name. */
    path?: string;
    /** set: short title. */
    title?: string;
    /** set: one line saying when to use these. */
    summary?: string;
    /** set: member section ids. */
    sections?: string[];
    /** set: member tool names (Tools groups). */
    tools?: string[];
  } & Record<string, JsonValue>;
  /** Manage notes. add: file a note under group_id; cites must name sections you read or "ref:" evidence. file: move a pending note (pending_id) under group_id, optionally rewriting text and adding cites. verify: re-read the sources of a stale note, then call this to refresh its hashes (optionally correcting text). retire: delete a filed note. drop: discard a pending note. A note can never cite another note. */
  map_note: {
    /** Map owner Session id; omit for your own conversation, specify for another map you curate. */
    root_session_id?: string;
    /** What to do. */
    action: "add" | "file" | "verify" | "retire" | "drop";
    /** Revision from map_view; the edit is rejected if the map moved on. */
    expected_revision: number;
    /** add, file: destination group. */
    group_id?: string;
    /** verify, retire: filed note. */
    note_id?: string;
    /** file, drop: pending note. */
    pending_id?: string;
    /** add: the note; file, verify: replacement text. */
    text?: string;
    /** add, file: section ids or "ref:…" evidence. */
    cites?: string[];
  } & Record<string, JsonValue>;
  /** Read the project map, core, pending notes, and stale flags. Follow nextPendingAfter as pending_after and nextGroupAfter as group_after even after edits. For a group with omittedNotes, read group_id with note_after from nextNoteAfter until complete. Group pages omit pending notes. */
  map_view: {
    /** Map owner Session id; omit for your own conversation, specify for another map you curate. */
    root_session_id?: string;
    /** Continue pending notes after this id; use nextPendingAfter. */
    pending_after?: string;
    /** Continue groups after this id; use nextGroupAfter, or an empty string to start groups only. */
    group_after?: string;
    /** Read one group and its notes without pending notes. */
    group_id?: string;
    /** Continue group_id notes after this id; use nextNoteAfter. */
    note_after?: string;
  } & Record<string, JsonValue>;
  /** Read a UTF-8 text file and return line-numbered content. */
  read: {
    /** Path to read, resolved by the filesystem backend. */
    file_path: string;
    /** 1-based first line to return. Defaults to 1. */
    offset?: number;
    /** Maximum number of lines to return. Defaults to 2000. */
    limit?: number;
  } & Record<string, JsonValue>;
  /** Read a PNG/JPEG/WebP/GIF file and return the image itself. Large images are downscaled automatically; do not install image libraries or create thumbnails to inspect an image. */
  read_image: {
    /** Path to the image file, resolved by the filesystem backend. */
    file_path: string;
  } & Record<string, JsonValue>;
  /** Load the full instructions for a skill. Call it before acting on a task that names or clearly matches a skill in the session skill catalog. */
  skill: {
    /** The exact skill name from the available skills list. */
    name: string;
  } & Record<string, JsonValue>;
  /** Record and update a task list to plan multi-step work and show progress; skip it for trivial single-step tasks. Add one todo per concrete step before you start. While work remains, keep the todos being worked on `in_progress`, several only when work runs in parallel. Mark each todo `completed` as soon as it is done. */
  todo_write: {
    /** The COMPLETE task list, replacing any previous list. */
    todos: ({
      /** What the task is — a short imperative line. */
      content: string;
      /** pending (not started) | in_progress (now) | completed (done). */
      status: "pending" | "in_progress" | "completed";
    })[];
  } & Record<string, JsonValue>;
  /** Fetch the content of a specific HTTP(S) URL and return it decoded to text. */
  web_fetch: {
    /** The HTTP(S) URL to fetch. */
    url: string;
  } & Record<string, JsonValue>;
  /** Create or fully replace a UTF-8 text file. */
  write: {
    /** Path to write, resolved by the filesystem backend. Provide `file_path` before `content` in the arguments. */
    file_path: string;
    /** Full UTF-8 text content to write. */
    content: string;
    /** The narrowest wider sandbox mode for a one-shot retry of the exact operation the sandbox just denied; the retry asks the user for approval. */
    sandbox_permissions?: "workspace-write" | "danger-full-access";
    /** Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access. Use the language of the user’s current request. */
    justification?: string;
  } & Record<string, JsonValue>;
}

interface ToolOutputMap {
  bash: {
    kind: "background";
    jobId: string;
    cwd: string;
  } | {
    kind: "promoted";
    cwd: string;
    jobId: string;
    timeoutMs: number;
    output: string;
  } | {
    kind: "foreground";
    cwd: string;
    exitCode: number | null;
    signal: string | null;
    timedOut: boolean;
    aborted: boolean;
    stopped?: string;
    timeoutMs: number;
    stdout: {
      text: string;
      truncated: boolean;
      spillPath?: string;
    };
    stderr: {
      text: string;
      truncated: boolean;
      spillPath?: string;
    };
    sandbox?: {
      mode: string;
      denied: boolean;
      enforcement?: string;
      runnerFailed?: boolean;
    };
  };
  context_browse: JsonValue;
  context_load: JsonValue;
  context_note: JsonValue;
  edit: {
    /** Canonical absolute path in the filesystem execution world. */
    path: string;
    before: string;
    after: string;
  };
  glob: {
    root: string;
    paths: string[];
  };
  grep: {
    matches: {
      path: string;
      lineNumber: number;
      line: string;
    }[];
  };
  map_core: JsonValue;
  map_group: JsonValue;
  map_note: JsonValue;
  map_view: JsonValue;
  read: {
    /** Canonical absolute path in the filesystem execution world. */
    path: string;
    offset: number;
    lines: {
      number: number;
      text: string;
    }[];
    totalLines: number;
  };
  read_image: {
    /** Canonical absolute path in the filesystem execution world. */
    path: string;
    image: {
      attachmentId: string;
      mediaType: "image/png" | "image/jpeg" | "image/webp" | "image/gif";
      bytes: number;
      width: number;
      height: number;
      name?: string;
      originalDimensions?: {
        width: number;
        height: number;
      };
    };
  };
  skill: {
    name: string;
    provider: string;
    resourceBase?: {
      kind: "directory";
      path: string;
    } | {
      kind: "url";
      url: string;
    } | {
      kind: "opaque";
      description: string;
    };
    content: string;
  };
  todo_write: {
    todos: ({
      content: string;
      status: "pending" | "in_progress" | "completed";
    })[];
    counts: {
      pending: number;
      inProgress: number;
      completed: number;
    };
  };
  web_fetch: {
    url: string;
    statusCode: number;
    body: {
      kind: "html";
      content: string;
    } | {
      kind: "text";
      content: string;
    };
    truncated: boolean;
  };
  write: {
    /** Canonical absolute path in the filesystem execution world. */
    path: string;
    operation: "create" | "update";
    before: string | null;
    after: string;
  };
}

type ToolName = keyof ToolOutputMap

declare class ToolCallError extends Error {
  readonly name: "ToolCallError";
  readonly toolName: ToolName;
}

declare const tools: {
  [K in ToolName]: (args: ToolArgsMap[K]) => Promise<ToolOutputMap[K]>;
}
